'use client';

import { useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabaseClient';
import { STARTER_CARDS } from './cards';
import { LANGS, type PracticeCard } from './types';

/**
 * Starter bank + cards generated by the daily refill pipeline
 * (public.practice_cards). Generated cards are cached in localStorage so they
 * work offline, and are appended after the starter bank in creation order,
 * so they are introduced once the bundled path for a language runs out.
 */

const KEY = 'secdigest_practice_cards_v1';
const KINDS = new Set(['output', 'bug', 'order', 'compare']);
const STARTER_IDS = new Set(STARTER_CARDS.map((card) => card.id));

let generated: PracticeCard[] | null = null;
let fetched = false;
const listeners = new Set<() => void>();

const isStringArray = (v: unknown): v is string[] => Array.isArray(v) && v.every((s) => typeof s === 'string');

/** Rows come from the network, so check the shape before rendering them. */
function isValidCard(raw: unknown): raw is PracticeCard {
  if (!raw || typeof raw !== 'object') return false;
  const c = raw as Record<string, unknown>;
  if (typeof c.id !== 'string' || typeof c.prompt !== 'string' || typeof c.explanation !== 'string') return false;
  if (typeof c.topic !== 'string' || !LANGS.includes(c.lang as never) || !KINDS.has(c.kind as string)) return false;
  switch (c.kind) {
    case 'output':
      return typeof c.code === 'string' && isStringArray(c.choices) && typeof c.answer === 'number' && c.answer >= 0 && c.answer < c.choices.length;
    case 'compare':
      return Array.isArray(c.choices) && typeof c.answer === 'number' && c.choices.every((ch) => ch && typeof (ch as { code?: unknown }).code === 'string');
    case 'bug':
      return isStringArray(c.lines) && typeof c.bugLine === 'number' && c.bugLine >= 0 && c.bugLine < c.lines.length;
    case 'order':
      return isStringArray(c.lines) && c.lines.length >= 3;
    default:
      return false;
  }
}

function loadCache(): PracticeCard[] {
  try {
    const raw = localStorage.getItem(KEY);
    const parsed: unknown = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.filter(isValidCard) : [];
  } catch {
    return [];
  }
}

async function refresh() {
  const { data, error } = await supabase
    .from('practice_cards')
    .select('card, created_at')
    .eq('active', true)
    .order('created_at', { ascending: true })
    .range(0, 4999);
  // Missing table (migration not run) or offline: keep whatever is cached.
  if (error) return;
  generated = (data ?? [])
    .map((row): unknown => ({ ...(row.card as object), generated: true }))
    .filter(isValidCard)
    .filter((card) => !STARTER_IDS.has(card.id));
  try {
    localStorage.setItem(KEY, JSON.stringify(generated));
  } catch {
    // ignore storage errors
  }
  listeners.forEach((fn) => fn());
}

/** All practice cards. Starter cards only during SSR / first render, so markup matches. */
export function usePracticeCards(): PracticeCard[] {
  const [version, setVersion] = useState(0);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    if (generated === null) generated = loadCache();
    setReady(true);
    const fn = () => setVersion((n) => n + 1);
    listeners.add(fn);
    if (!fetched) {
      fetched = true;
      void refresh();
    }
    return () => {
      listeners.delete(fn);
    };
  }, []);

  return useMemo(
    () => (ready && generated && generated.length > 0 ? [...STARTER_CARDS, ...generated] : STARTER_CARDS),
    // `version` changes whenever the module-level `generated` list is replaced.
    [ready, version]
  );
}
